  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 17, $j$5.1 Factoring$j$, $j${"body": "Factoring turns a sum of terms into a product. Always look first for a greatest common factor (GCF).\n\nGCF: 6x² + 9x = 3x(2x + 3).\nTrinomial x² + bx + c: find two numbers that multiply to c and add to b. x² + 7x + 12 = (x + 3)(x + 4). x² − 5x − 14 = (x − 7)(x + 2).\nDifference of squares: A² − B² = (A − B)(A + B). x² − 49 = (x − 7)(x + 7).\nLeading coefficient not 1: 2x² + 7x + 3. Multiply 2 × 3 = 6, find two numbers with product 6 and sum 7 (1 and 6), split the middle term, and group: 2x² + x + 6x + 3 = x(2x + 1) + 3(2x + 1) = (2x + 1)(x + 3).\n\nAlways check by multiplying back.\n\nThink it through: factoring is multiplication run backward, so you can always check by multiplying. Follow this order. First pull out any greatest common factor. Then look at the number of terms. A binomial that is a difference of squares factors as (A − B)(A + B). A trinomial needs two numbers that multiply to c and add to b. A sign hint: if c is positive, both numbers share the sign of b. If c is negative, the numbers have opposite signs. Check: (x + 3)(x + 4) = x² + 4x + 3x + 12 = x² + 7x + 12, which matches.\n\nYour task: factor (a) x² + 9x + 20 (b) 4x² − 25 (c) 3x² − 12x (d) x² − 2x − 15.\n\nFlorida standards: MA.912.AR.1.7.", "video": "", "script": "Welcome to Unit 5. Factoring is the reverse of multiplying. In Unit 1 we multiplied factors to get a sum of terms. Now we go backward. Factoring turns a sum of terms into a product, and it is the key that unlocks quadratic equations.\n\nAlways begin by looking for a greatest common factor. In six x squared plus nine x, both terms share a factor of three x. Pull it out and we have three x times the quantity two x plus three. To check, multiply it back. Three x times two x is six x squared, and three x times three is nine x. It matches.\n\nNext, trinomials that look like x squared plus b x plus c. We search for two numbers that multiply to c and add to b. For x squared plus seven x plus twelve, we need a product of twelve and a sum of seven. Three and four do it. So the factors are x plus three and x plus four. When the last term is negative, the two numbers have opposite signs. For x squared minus five x minus fourteen, we need a product of negative fourteen and a sum of negative five. Negative seven and positive two work, so we get x minus seven times x plus two.\n\nThe third pattern is the difference of squares. A squared minus B squared equals A minus B times A plus B. So x squared minus forty nine factors as x minus seven times x plus seven. And four x squared minus twenty five factors as two x minus five times two x plus five. The middle terms cancel, which is why there is no x term. Be careful: a sum of squares, like x squared plus nine, does not factor this way.\n\nFinally, when the leading coefficient is not one, as in two x squared plus seven x plus three, multiply the first and last numbers to get six. Find two numbers that multiply to six and add to seven. They are one and six. Split the middle term: two x squared plus x plus six x plus three. Now group. Take x out of the first pair to get x times two x plus one. Take three out of the second pair to get three times two x plus one. Both groups share the binomial two x plus one, so the answer is two x plus one times x plus three.\n\nYour task today is to factor four expressions and check each one by multiplying. Then take the four question check.\n\nPaul wrote, as a wise masterbuilder, I have laid the foundation. Factoring is foundation work, and strong foundations hold up everything built on them. Excellence, Faith, Purpose. I will see you in the next lesson.", "readings": [], "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MA.912.AR.1.7"}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.1 Factoring$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 18, $j$5.2 Solving Quadratic Equations$j$, $j${"body": "A quadratic equation has the form ax² + bx + c = 0. Its solutions are also called roots or zeros. There are three main methods.\n\n1. Factoring and the zero product property. x² − 5x + 6 = 0 gives (x − 2)(x − 3) = 0, so x = 2 or x = 3.\n2. Square roots. x² = 49 gives x = ±7. (x − 3)² = 16 gives x − 3 = ±4, so x = 7 or x = −1.\n3. The quadratic formula: x = (−b ± √(b² − 4ac)) / (2a). For 2x² + 3x − 2 = 0: b² − 4ac = 9 + 16 = 25, so x = (−3 ± 5)/4, giving x = 1/2 or x = −2.\n\nThe discriminant b² − 4ac tells how many real solutions there are: positive gives two, zero gives one, negative gives none.\n\nThink it through: choose the method that fits the equation. If it factors easily, factor. If it looks like (x − h)² = k, take square roots and remember the plus or minus. Otherwise use the quadratic formula, which always works. Before you factor, set the equation equal to zero. The zero product property says that if a product equals zero, one factor must be zero, and it works only when the product is zero. So x² + x = 6 cannot be solved by writing x(x + 1) = 6 and setting x = 6. Move the 6 first: x² + x − 6 = 0. Check each solution in the original equation.\n\nYour task: solve (a) x² − x − 12 = 0 (b) x² = 81 (c) 3x² − 5x − 2 = 0 (d) (x + 2)² = 25.\n\nFlorida standards: MA.912.AR.3.1.", "video": "", "script": "A quadratic equation is an equation that can be written as a x squared plus b x plus c equals zero. Its solutions are called roots or zeros. Today we learn three reliable methods to find them.\n\nMethod one is factoring, and it rests on the zero product property. If two numbers multiply to give zero, then at least one of them must be zero. Take x squared minus five x plus six equals zero. It factors as x minus two times x minus three equals zero. So either x minus two is zero, or x minus three is zero. The solutions are x equals two and x equals three. Always get zero on one side before you factor.\n\nMethod two uses square roots. When the equation is x squared equals forty nine, x can be seven or negative seven, because both square to forty nine. We write x equals plus or minus seven. If the equation is x minus three, all squared, equals sixteen, take the square root of both sides to get x minus three equals plus or minus four. Then x equals seven, or x equals negative one.\n\nMethod three is the quadratic formula, which works on every quadratic. It says x equals negative b, plus or minus the square root of b squared minus four a c, all over two a. Let us use it on two x squared plus three x minus two equals zero. Here a is two, b is three, and c is negative two. The part under the radical is nine minus four times two times negative two, which is nine plus sixteen, which is twenty five. The square root is five. So x equals negative three plus or minus five, all over four. That gives two fourths, or one half, and negative eight fourths, or negative two. We can check by factoring: two x minus one times x plus two gives two x squared plus three x minus two. It works.\n\nThe part under the radical has a name, the discriminant. If it is positive, there are two real solutions. If it is zero, there is exactly one. If it is negative, there are no real solutions, because we cannot take the square root of a negative number in the real numbers.\n\nYour task today is to solve four equations, choosing the best method for each, and to check your answers. Then take the four question check.\n\nSolomon wrote, Wisdom is the principal thing; therefore get wisdom. Choosing the right method is wisdom in action. Excellence, Faith, Purpose. I will see you in the next lesson.", "readings": [], "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MA.912.AR.3.1"}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.2 Solving Quadratic Equations$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 19, $j$5.3 Graphing Quadratics$j$, $j${"body": "The graph of y = ax² + bx + c is a parabola. It opens up if a > 0 (the vertex is a minimum) and down if a < 0 (the vertex is a maximum).\n\nAxis of symmetry: x = −b/(2a). The vertex lies on it. Find the y coordinate by substituting.\nY intercept: (0, c). Zeros (x intercepts): solve ax² + bx + c = 0.\n\nWorked example: y = x² − 4x + 3. Axis x = 4/2 = 2. Vertex (2, 2² − 8 + 3) = (2, −1). Y intercept (0, 3). Zeros: (x − 1)(x − 3) = 0 gives x = 1 and x = 3. It opens up.\n\nVertex form: y = a(x − h)² + k has vertex (h, k). For example y = (x − 2)² + 1 has vertex (2, 1).\n\nThink it through: to graph a parabola, follow four steps. First decide whether it opens up or down from the sign of a. Second find the axis x = −b/(2a). Third find the vertex by substituting that x value. Fourth find the intercepts. Be careful with signs: for y = x² − 4x + 3, b is −4, so the axis is x = 4/2 = 2. A parabola is symmetric, so every point has a mirror image across the axis. The y intercept (0, 3) has a partner at (4, 3), two units on each side of x = 2. Use these mirror points to sketch a smooth curve.\n\nYour task: for (a) y = x² + 6x + 5 find the axis, vertex, y intercept and zeros. (b) For y = −2x² + 4x find the vertex and zeros and say whether the vertex is a maximum or a minimum.\n\nFlorida standards: MA.912.AR.3.6, MA.912.AR.3.7.", "video": "", "script": "Every time a basketball is thrown, a fountain sprays, or a cable hangs between two towers, a curve called a parabola appears. The graph of y equals a x squared plus b x plus c is a parabola, and today we learn to sketch one quickly from its key features.\n\nFirst, direction. If a is positive, the parabola opens up like a smile, and the vertex is the lowest point, a minimum. If a is negative, it opens down like a frown, and the vertex is the highest point, a maximum.\n\nSecond, the axis of symmetry. This is a vertical line through the vertex, and it cuts the parabola into two matching halves. Its equation is x equals negative b over two a. Let us use y equals x squared minus four x plus three. Here a is one and b is negative four, so x equals four over two, which is two. The axis is x equals two.\n\nThird, the vertex. Its x coordinate is two. Substitute two into the equation: four minus eight plus three is negative one. So the vertex is two comma negative one.\n\nFourth, the y intercept. Set x to zero, and y equals c. Here the y intercept is zero comma three.\n\nFifth, the zeros, also called x intercepts. Set y to zero and solve: x squared minus four x plus three factors as x minus one times x minus three. So the zeros are one and three. Notice that two is exactly halfway between one and three. That is symmetry at work.\n\nWith the vertex, the intercepts and the direction, you can sketch the whole curve. \n\nThere is also vertex form, y equals a times x minus h, squared, plus k. The vertex is h comma k. Notice the sign: the graph of y equals x minus two, squared, plus one has its vertex at two comma one, shifted right two and up one from the basic parabola.\n\nYour task today is to find the axis, vertex, intercepts and zeros for two parabolas and tell whether each vertex is a maximum or a minimum. Then take the four question check.\n\nThe Psalmist wrote, weeping may endure for a night, but joy cometh in the morning. A parabola reminds us that low points are turning points, and the curve rises again. Excellence, Faith, Purpose. I will see you in the next lesson.", "readings": [], "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MA.912.AR.3.6, MA.912.AR.3.7"}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.3 Graphing Quadratics$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 20, $j$5.4 Writing Quadratic Functions and Models$j$, $j${"body": "From zeros: if the zeros are r and s, then y = a(x − r)(x − s). Use another point to find a.\nExample: zeros 1 and 3, through (0, 6). 6 = a(0 − 1)(0 − 3) = 3a, so a = 2. Then y = 2(x − 1)(x − 3) = 2x² − 8x + 6.\n\nProjectile model: h(t) = −16t² + v t + s, in feet, where t is seconds, v is the starting upward speed and s is the starting height. For h(t) = −16t² + 64t + 5: the maximum occurs at t = −64/(2·(−16)) = 2 seconds, and h(2) = −64 + 128 + 5 = 69 feet. The object lands when h(t) = 0, at about t = 4.08 seconds (use the quadratic formula and keep the positive answer).\n\nArea model: a pen with 40 feet of fence and area A = x(20 − x) is largest at x = 10, giving 100 square feet.\n\nThink it through: quadratic models answer questions about the highest point, the lowest point, and when something hits zero. The vertex gives the maximum when the parabola opens down. In h(t) = −16t² + 64t + 5, the number 16 comes from gravity measured in feet and seconds. Read your answers with units: 2 seconds and 69 feet. When you solve for the landing time, you may get a negative value as well as a positive one. Time cannot be negative here, so reject it and keep the positive answer. Always ask whether an answer makes sense in the story.\n\nYour task: (a) Write the quadratic with zeros −2 and 4 through (0, −16). (b) For h(t) = −16t² + 32t + 6, find the time and height at the peak. (c) A pen uses 60 feet of fence and has area A = x(30 − x). Find the maximum area.\n\nFlorida standards: MA.912.AR.3.4, MA.912.AR.3.5, MA.912.AR.3.8.", "video": "", "script": "Today we use quadratics to describe real situations and to build equations from information. There are two tasks: writing a quadratic from its zeros, and modeling motion and area.\n\nIf you know the zeros of a quadratic, call them r and s, then the function has the form y equals a, times x minus r, times x minus s. The number a is a stretch factor, and we find it using one more point. Suppose the zeros are one and three, and the graph passes through zero comma six. Substitute x equals zero and y equals six. Zero minus one is negative one, zero minus three is negative three, and their product is three. So six equals three a, and a equals two. The function is y equals two, times x minus one, times x minus three. Multiply it out and you get two x squared minus eight x plus six.\n\nNow motion. When an object is thrown upward, its height in feet after t seconds is modeled by h of t equals negative sixteen t squared plus v t plus s, where v is the starting speed and s is the starting height. Take h of t equals negative sixteen t squared plus sixty four t plus five. The graph is a parabola opening down, so the vertex is the maximum. The time of the peak is negative b over two a, which is negative sixty four over negative thirty two, which is two seconds. The height at that time is negative sixty four plus one hundred twenty eight plus five, which is sixty nine feet.\n\nWhen does it land? Set the height to zero and use the quadratic formula. The discriminant is four thousand ninety six plus three hundred twenty, which is four thousand four hundred sixteen. The square root is about sixty six point four five. Keep the positive time, which is about four point zero eight seconds. A negative time makes no sense here, so we reject it. Always ask whether an answer fits the story.\n\nArea problems work the same way. If a farmer has forty feet of fence for a rectangular pen, one side x forces the other side to be twenty minus x, so the area is x times twenty minus x. This parabola opens down with zeros at zero and twenty, so its peak is at x equals ten, where the area is one hundred square feet.\n\nYour task today is to write one quadratic from its zeros, find a peak, and maximize an area. Then take the four question check.\n\nScripture records that David took a stone, and slang it, and smote the Philistine. That stone followed a parabola, and the one who aims well, with God's help, wins. Excellence, Faith, Purpose. I will see you in the next lesson.", "readings": [], "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MA.912.AR.3.4, MA.912.AR.3.5, MA.912.AR.3.8"}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.4 Writing Quadratic Functions and Models$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 5, $j$Assessment 5: Polynomials, Factoring and Quadratics, Show Your Work$j$, $j${"prompt": "Show every step. (1) Factor completely: x² + 8x + 15, 9x² − 49, and 2x² − 7x + 3. (2) Solve x² − 3x − 10 = 0 by factoring. (3) Solve 2x² + 5x − 3 = 0 with the quadratic formula. (4) For y = x² + 2x − 8, give the axis of symmetry, the vertex, the y intercept and the zeros, and tell whether the vertex is a maximum or a minimum. (5) Write a quadratic with zeros 2 and 5 that passes through (0, 20). (6) A rocket model has height h(t) = −16t² + 96t + 4 feet. Find the time of the peak, the maximum height, and explain in a sentence why the negative time answer is rejected when finding the landing time.", "rubric": "Total 100. Item 1: 18 (6 each). Item 2: 12 (x = 5 or x = −2). Item 3: 14 (discriminant 49, x = 1/2 or x = −3). Item 4: 20 (axis x = −1, vertex (−1, −9), y intercept (0, −8), zeros 2 and −4, minimum). Item 5: 12 (a = 2, y = 2(x − 2)(x − 5)). Item 6: 24 (peak at 3 seconds 8, maximum height 148 feet 8, reason that time cannot be negative 8). Show of work counts in every item."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 5: Polynomials, Factoring and Quadratics, Show Your Work$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 5, $j$Discussion 5: The Shape of a Rise$j$, $j${"prompt": "A parabola goes down before it comes up, or up before it comes down. Describe a time in your life or ministry that felt like a vertex, a turning point. What changed after it? Explain how the idea of a maximum or a minimum helps you think about it. Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 5: The Shape of a Rise$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 21, $j$Check 5.1: Factoring$j$, $j${"questions": [{"q": "Factor x² + 5x + 6.", "options": ["(x + 5)(x + 1)", "(x − 2)(x − 3)", "(x + 2)(x + 3)", "(x + 1)(x + 6)"]}, {"q": "Factor x² − 81.", "options": ["(x − 3)(x + 27)", "(x − 9)(x − 9)", "(x − 9)(x + 9)", "(x + 9)(x + 9)"]}, {"q": "Factor 10x² + 15x.", "options": ["10x(x + 15)", "5(2x² + 3x)", "x(10x + 15)", "5x(2x + 3)"]}, {"q": "Factor 2x² + 5x + 2.", "options": ["(2x + 2)(x + 1)", "(2x − 1)(x − 2)", "(x + 5)(2x + 2)", "(2x + 1)(x + 2)"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: Factoring$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,3,3}'::int[], array[$j$2 and 3 multiply to 6 and add to 5.$j$,$j$A difference of squares factors as (A − B)(A + B).$j$,$j$The GCF is 5x.$j$,$j$(2x + 1)(x + 2) = 2x² + 4x + x + 2 = 2x² + 5x + 2.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: Factoring$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 22, $j$Check 5.2: Solving Quadratic Equations$j$, $j${"questions": [{"q": "Solve x² − 7x + 10 = 0.", "options": ["x = −2 or x = 5", "x = 2 or x = 5", "x = −2 or x = −5", "x = 1 or x = 10"]}, {"q": "Solve x² = 36.", "options": ["x = 6 only", "x = 36", "x = 18", "x = 6 or x = −6"]}, {"q": "What is the discriminant of x² + 2x + 5, and how many real solutions are there?", "options": ["0, one", "−16, none", "16, two", "24, two"]}, {"q": "Solve (x − 1)² = 9.", "options": ["x = 10 or x = −8", "x = 4 or x = −2", "x = 4 only", "x = 3 or x = −3"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: Solving Quadratic Equations$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,1,1}'::int[], array[$j$(x − 2)(x − 5) = 0.$j$,$j$Both 6 and −6 square to 36.$j$,$j$4 − 20 = −16, which is negative, so there are no real solutions.$j$,$j$x − 1 = ±3, so x = 4 or x = −2.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: Solving Quadratic Equations$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 23, $j$Check 5.3: Graphing Quadratics$j$, $j${"questions": [{"q": "What is the axis of symmetry of y = x² − 6x + 8?", "options": ["x = 6", "x = 8", "x = −3", "x = 3"]}, {"q": "What is the vertex of y = x² − 6x + 8?", "options": ["(3, 1)", "(3, −1)", "(6, 8)", "(−3, −1)"]}, {"q": "A parabola opens down when:", "options": ["c < 0", "a < 0", "b < 0", "a > 0"]}, {"q": "What is the y intercept of y = 2x² − 3x + 7?", "options": ["(0, −3)", "(0, 2)", "(7, 0)", "(0, 7)"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Graphing Quadratics$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,1,3}'::int[], array[$j$x = −b/(2a) = 6/2 = 3.$j$,$j$At x = 3, y = 9 − 18 + 8 = −1.$j$,$j$A negative leading coefficient opens the parabola down.$j$,$j$The y intercept is (0, c).$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Graphing Quadratics$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 24, $j$Check 5.4: Writing Quadratic Functions and Models$j$, $j${"questions": [{"q": "Which quadratic has zeros 1 and 3 and passes through (0, 6)?", "options": ["y = 2(x − 1)(x − 3)", "y = (x − 1)(x − 3)", "y = 6(x − 1)(x − 3)", "y = 3(x − 1)(x − 3)"]}, {"q": "A ball's height is h(t) = −16t² + 64t + 5. What is the maximum height?", "options": ["133 feet", "64 feet", "5 feet", "69 feet"]}, {"q": "At what time does the ball in the previous question reach its peak?", "options": ["1 second", "2 seconds", "4 seconds", "69 seconds"]}, {"q": "A rectangle's area is A = x(20 − x). What value of x gives the maximum area?", "options": ["5", "10", "20", "40"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Writing Quadratic Functions and Models$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,1,1}'::int[], array[$j$6 = a(3) gives a = 2.$j$,$j$The peak is at t = 2, and h(2) = 69.$j$,$j$t = −b/(2a) = −64/(−32) = 2.$j$,$j$The parabola's zeros are 0 and 20, so the peak is halfway at x = 10.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Writing Quadratic Functions and Models$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 25, $j$Unit Quiz 5: Polynomials, Factoring and Quadratics$j$, $j${"questions": [{"q": "Factor x² − 16.", "options": ["(x − 4)(x − 4)", "(x − 8)(x + 2)", "(x + 16)(x − 1)", "(x − 4)(x + 4)"]}, {"q": "Solve x² + x − 6 = 0.", "options": ["x = 1 or x = −6", "x = 2 or x = −3", "x = −2 or x = 3", "x = 6 or x = −1"]}, {"q": "What is the vertex of y = (x − 1)² + 4?", "options": ["(1, 4)", "(−1, 4)", "(4, 1)", "(1, −4)"]}, {"q": "What is the discriminant of x² − 6x + 9?", "options": ["36", "−36", "18", "0"]}, {"q": "Factor 6x² + 9x.", "options": ["3x(2x + 3)", "6x(x + 9)", "3(2x² + 3x)", "x(6x + 9)"]}, {"q": "A ball has height h(t) = −16t² + 32t + 6. What is its maximum height?", "options": ["22 feet", "6 feet", "32 feet", "38 feet"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: Polynomials, Factoring and Quadratics$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,0,3,0,0}'::int[], array[$j$A difference of squares.$j$,$j$(x + 3)(x − 2) = 0.$j$,$j$In vertex form the vertex is (h, k).$j$,$j$36 − 36 = 0, so there is exactly one real solution.$j$,$j$The GCF is 3x.$j$,$j$The peak is at t = 1, and h(1) = −16 + 32 + 6 = 22.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: Polynomials, Factoring and Quadratics$j$ on conflict (item_id) do nothing;
